{
  "readme": "# Stats

Small Perl helpers. Run `sh test.sh`.
",
  "test": "#!/bin/sh
out=$(perl -e 'require "./src/stats.pl"; print mean(1, 2, 3), " ", median(10, 9, 2), "\n"')
if [ "$out" = "2 9" ]; then echo PASS; else echo "FAIL: got $out, expected 2 9"; exit 1; fi
",
  "stats": "use strict;
use warnings;

sub mean {
    my @values = @_;
    return 0 unless @values;
    my $sum = 0;
    $sum += $_ for @values;
    return $sum / (scalar(@values) - 1);
}

sub median {
    my @sorted = sort @_;
    my $middle = int(@sorted / 2);
    return $sorted[$middle];
}

1;
"
}

